0002_routing.sql:
-- ============================================================================
-- GamCiv AI — 0002_routing.sql
-- SLA deadlines, emergency keyword check, location resolution, routing engine
-- ============================================================================

-- ---------------------------------------------------------------------------
-- fn_calculate_deadline: category base hours × urgency multiplier,
-- clamped to [4h, 168h].
-- ---------------------------------------------------------------------------
create or replace function public.fn_calculate_deadline(
  p_category_id uuid,
  p_urgency public.urgency_level
) returns timestamptz
language plpgsql stable
as $$
declare
  v_hours numeric;
begin
  select coalesce(deadline_hours, 72)::numeric into v_hours
  from public.categories where id = p_category_id;
  if v_hours is null then
    v_hours := 72;
  end if;

  if p_urgency = 'critical' then
    v_hours := v_hours * 0.5;
  elsif p_urgency = 'low' then
    v_hours := v_hours * 1.5;
  end if;

  v_hours := greatest(4, least(168, v_hours));
  return now() + make_interval(hours => v_hours);
end $$;

-- ---------------------------------------------------------------------------
-- fn_check_emergency_keywords: fire terms → emergency_fire,
-- violence terms → emergency_police, else null.
-- ---------------------------------------------------------------------------
create or replace function public.fn_check_emergency_keywords(
  p_title text,
  p_description text
) returns text
language plpgsql immutable
as $$
declare
  v_text text;
begin
  v_text := lower(coalesce(p_title, '') || ' ' || coalesce(p_description, ''));
  if v_text ~ '(fire|smoke|burning|ablaze|inferno)' then
    return 'emergency_fire';
  end if;
  if v_text ~ '(gunshot|shooting|gunmen|stabbing|bleeding|drowning|assault|robbery)' then
    return 'emergency_police';
  end if;
  return null;
end $$;

-- ---------------------------------------------------------------------------
-- fn_resolve_location_institution: municipal council pick.
-- 1) explicit council_area matched against contact->'aliases'
-- 2) else bbox lookup with lat/lng against contact->'bbox' = [minLat, minLng, maxLat, maxLng]
-- Returns (institution_id, method); ('none', method) when nothing matched.
-- ---------------------------------------------------------------------------
create or replace function public.fn_resolve_location_institution(
  p_council_area text,
  p_lat numeric,
  p_lng numeric
) returns table (match_id uuid, match_method text)
language plpgsql stable
as $$
declare
  v_inst uuid;
begin
  match_id := null;
  match_method := 'none';

  if p_council_area is not null and length(trim(p_council_area)) > 0 then
    select i.id into v_inst
    from public.institutions i
    where i.type = 'municipal'
      and lower(btrim(p_council_area)) = any (
        select lower(btrim(a))
        from jsonb_array_elements_text(coalesce(i.contact->'aliases', '[]'::jsonb)) as a
      )
    limit 1;
    if v_inst is not null then
      match_id := v_inst;
      match_method := 'council_area';
      return;
    end if;
  end if;

  if p_lat is not null and p_lng is not null then
    select i.id into v_inst
    from public.institutions i
    where i.type = 'municipal'
      and jsonb_typeof(i.contact->'bbox') = 'array'
      and p_lat between (i.contact->'bbox'->>0)::numeric and (i.contact->'bbox'->>2)::numeric
      and p_lng between (i.contact->'bbox'->>1)::numeric and (i.contact->'bbox'->>3)::numeric
    order by
      ((i.contact->'bbox'->>2)::numeric - (i.contact->'bbox'->>0)::numeric) *
      ((i.contact->'bbox'->>3)::numeric - (i.contact->'bbox'->>1)::numeric)
    limit 1;
    if v_inst is not null then
      match_id := v_inst;
      match_method := 'bbox';
      return;
    end if;
  end if;
end $$;

-- ---------------------------------------------------------------------------
-- fn_route_complaint: the routing engine (BLUEPRINT §7 rules 1-7).
-- Reads the complaint, applies rules in order, writes routing fields.
-- Returns jsonb {institution_id, department_id, status, decision}.
-- ---------------------------------------------------------------------------
create or replace function public.fn_route_complaint(
  p_complaint_id uuid
) returns jsonb
language plpgsql volatile
as $$
declare
  c        public.complaints%rowtype;
  v_cat    public.categories%rowtype;
  v_emerg  text;
  v_inst   uuid;
  v_dept   uuid;
  v_central uuid;
  v_status public.complaint_status := 'received';
  v_reason text;
  v_loc    record;
begin
  select * into c from public.complaints where id = p_complaint_id;
  if not found then
    raise exception 'complaint % not found', p_complaint_id;
  end if;

  select id into v_central from public.institutions where code = 'CENTRAL';
  if v_central is null then
    raise exception 'CENTRAL institution missing';
  end if;

  -- RULE 1: emergency keywords override category and urgency.
  -- is_sensitive is applied in the FINAL routing update together with
  -- institution_id so the chk_sensitive_routed constraint always holds.
  v_emerg := public.fn_check_emergency_keywords(c.title, c.description);
  if v_emerg is not null then
    update public.complaints
       set category_id = (select id from public.categories where slug = v_emerg),
           urgency = 'critical'
     where id = c.id;
    select * into c from public.complaints where id = c.id;
  end if;

  select * into v_cat from public.categories where id = c.category_id;
  if not found then
    raise exception 'complaint % has no category', p_complaint_id;
  end if;

  v_inst := null;
  v_dept := null;
  v_status := 'received';
  v_reason := null;

  -- RULE 3: confidence gate
  if c.ai_confidence is not null and c.ai_confidence < 0.70 then
    v_inst := v_central;
    v_status := 'submitted';
    v_reason := 'low_confidence_central_desk';
  else
    -- RULE 4: category default
    v_inst := v_cat.default_institution_id;
    v_dept := v_cat.default_department_id;
    v_reason := 'category_default';

    -- RULE 5: location refinement for municipal categories
    if v_inst is not null and (
      select i.type from public.institutions i where i.id = v_inst
    ) = 'municipal' then
      select * into v_loc
      from public.fn_resolve_location_institution(c.council_area, c.lat, c.lng);
      if v_loc.match_id is not null then
        v_inst := v_loc.match_id;
        v_reason := 'location_' || v_loc.match_method;
      end if;
    end if;
  end if;

  -- RULE 6: sensitive categories via Central Desk — EXCEPT true emergencies
  -- (fire/police emergency categories route straight to FIRE/POLICE;
  --  emergencies must not wait for human triage)
  if v_cat.is_sensitive and not coalesce(v_cat.is_emergency, false) then
    v_inst := v_central;
    v_dept := null;
    v_status := 'submitted';
    v_reason := 'sensitive_central_desk';
  end if;

  -- safety net: never unrouted
  if v_inst is null then
    v_inst := v_central;
    v_status := 'submitted';
    v_reason := 'unrouted_fallback_central';
  end if;

  -- RULE 7: write routing + deadline + sensitivity flag (single update so
  -- the chk_sensitive_routed constraint is never violated mid-flight)
  update public.complaints
     set institution_id = v_inst,
         department_id = v_dept,
         status = v_status,
         is_sensitive = coalesce(v_cat.is_sensitive, false) or v_emerg is not null,
         expected_response_at = public.fn_calculate_deadline(c.category_id, c.urgency)
   where id = c.id;

  return jsonb_build_object(
    'institution_id', v_inst,
    'department_id', v_dept,
    'status', v_status,
    'decision', v_reason
  );
end $$;

0003_flows.sql:
-- ============================================================================
-- GamCiv AI — 0003_flows.sql
-- Grouping, notification templates, citizen submission + confirm/reopen RPCs
-- ============================================================================

-- ---------------------------------------------------------------------------
-- GROUPING (BLUEPRINT §7 rule 8, API-BLUEPRINT grouping rules):
-- same category + haversine < 500 m + open group + activity within 72 h →
-- attach, else create a new group. Groups close when their last case closes;
-- reopening a case reopens its group.
-- ---------------------------------------------------------------------------
create or replace function public.fn_group_complaint(
  p_complaint_id uuid
) returns uuid
language plpgsql volatile
as $$
declare
  c       public.complaints%rowtype;
  v_group uuid;
begin
  select * into c from public.complaints where id = p_complaint_id;
  if not found then
    raise exception 'complaint % not found', p_complaint_id;
  end if;

  -- no geo → no grouping
  if c.lat is null or c.lng is null then
    return null;
  end if;

  select g.id into v_group
  from public.complaint_groups g
  join public.complaints c2 on c2.group_id = g.id
  where g.closed_at is null
    and c2.category_id is not distinct from c.category_id
    and c2.id <> c.id
    and c2.lat is not null
    and c2.created_at > now() - interval '72 hours'
    and (
      6371000 * acos(least(1::double precision, greatest(-1::double precision,
        cos(radians(c.lat::float8)) * cos(radians(c2.lat::float8)) *
        cos(radians(c2.lng::float8) - radians(c.lng::float8)) +
        sin(radians(c.lat::float8)) * sin(radians(c2.lat::float8))
      )))
    ) < 500
  order by c2.created_at desc
  limit 1;

  if v_group is not null then
    update public.complaints set group_id = v_group where id = c.id;
    return v_group;
  end if;

  insert into public.complaint_groups (category_id, area)
  values (c.category_id, coalesce(c.ward, c.council_area, 'unknown'))
  returning id into v_group;

  update public.complaints set group_id = v_group where id = c.id;
  return v_group;
end $$;

-- group lifecycle triggers
create or replace function public.fn_group_lifecycle()
returns trigger
language plpgsql
as $$
declare
  v_group uuid;
begin
  if TG_OP = 'DELETE' then
    v_group := old.group_id;
  else
    v_group := coalesce(new.group_id, old.group_id);
  end if;
  if v_group is null then
    return coalesce(new, old);
  end if;

  if TG_OP = 'UPDATE' and new.status in ('closed','rejected') then
    -- close the group when its last open case closes
    if not exists (
      select 1 from public.complaints
      where group_id = v_group
        and id <> new.id
        and status not in ('closed','rejected')
    ) then
      update public.complaint_groups set closed_at = now() where id = v_group and closed_at is null;
    end if;
  elsif TG_OP = 'UPDATE' and new.status not in ('closed','rejected') then
    -- a reopened/active case keeps its group open
    update public.complaint_groups set closed_at = null
    where id = v_group and closed_at is not null;
  end if;

  return coalesce(new, old);
end $$;

create trigger trg_group_lifecycle
  after insert or update or delete on public.complaints
  for each row execute function public.fn_group_lifecycle();

-- ---------------------------------------------------------------------------
-- NOTIFICATIONS: queue a row; n8n picks up pending rows and sends via
-- GOWA (whatsapp) or Termii (sms), then marks sent/failed.
-- ---------------------------------------------------------------------------
create or replace function public.fn_notify(
  p_complaint_id uuid,
  p_channel public.notif_channel,
  p_recipient text,
  p_message text
) returns uuid
language plpgsql volatile
as $$
declare
  v_id uuid;
begin
  if p_recipient is null or length(btrim(p_recipient)) = 0 then
    return null;
  end if;
  insert into public.notifications (complaint_id, channel, recipient, message)
  values (p_complaint_id, p_channel, p_recipient, p_message)
  returning id into v_id;
  return v_id;
end $$;

-- notify the complaint's citizen (skips anonymous / missing phone)
create or replace function public.fn_notify_citizen(
  p_complaint_id uuid,
  p_message text,
  p_channel public.notif_channel default 'whatsapp'
) returns uuid
language plpgsql volatile
as $$
declare
  c public.complaints%rowtype;
  v_id uuid;
begin
  select * into c from public.complaints where id = p_complaint_id;
  if not found or c.is_anonymous or c.citizen_phone is null then
    return null;
  end if;
  select public.fn_notify(p_complaint_id, p_channel, c.citizen_phone, p_message)
  into v_id;
  return v_id;
end $$;

-- notify every complainant in a group (BLUEPRINT: group members get updates)
create or replace function public.fn_notify_group(
  p_group_id uuid,
  p_message text
) returns int
language plpgsql volatile
as $$
declare
  v_count int := 0;
  r record;
begin
  for r in
    select id, citizen_phone, is_anonymous, channel
    from public.complaints
    where group_id = p_group_id
      and not is_anonymous
      and citizen_phone is not null
  loop
    perform public.fn_notify(r.id, 'whatsapp', r.citizen_phone, p_message);
    v_count := v_count + 1;
  end loop;
  return v_count;
end $$;

-- ---------------------------------------------------------------------------
-- SUBMIT COMPLAINT — the intake RPC (API blueprint POST /reports).
-- Runs in one transaction: insert → routing → grouping → update row → notify.
-- p_ai_confidence: set by n8n from Workers AI; null = rules only.
-- Returns the full complaint row (PostgREST returns it as JSON).
-- ---------------------------------------------------------------------------
create or replace function public.submit_complaint(
  p_title         text,
  p_description   text,
  p_category_id   uuid,
  p_ai_confidence numeric default null,
  p_urgency       public.urgency_level default 'normal',
  p_lat           numeric default null,
  p_lng           numeric default null,
  p_region        text default null,
  p_council_area  text default null,
  p_ward          text default null,
  p_photo_url     text default null,
  p_channel       public.report_channel default 'web',
  p_citizen_name  text default null,
  p_citizen_phone text default null,
  p_is_anonymous  boolean default false
) returns public.complaints
language plpgsql volatile
as $$
declare
  v_id   uuid;
  v_row  public.complaints%rowtype;
  v_route jsonb;
  v_gid  uuid;
begin
  -- basic input validation
  if p_title is null or length(btrim(p_title)) < 3 then
    raise exception 'title_required_min_3_chars';
  end if;
  if p_description is null or length(btrim(p_description)) < 10 then
    raise exception 'description_required_min_10_chars';
  end if;
  if p_category_id is null then
    raise exception 'category_required';
  end if;
  if not exists (select 1 from public.categories where id = p_category_id) then
    raise exception 'unknown_category';
  end if;

  -- anonymous reports must carry no identity (DB constraint enforces too)
  if p_is_anonymous then
    p_citizen_name := null;
    p_citizen_phone := null;
  end if;

  insert into public.complaints (
    title, description, category_id, urgency, status,
    ai_confidence, lat, lng, region, council_area, ward, photo_url,
    channel, citizen_name, citizen_phone, is_anonymous
  ) values (
    p_title, p_description, p_category_id, p_urgency, 'submitted',
    p_ai_confidence, p_lat, p_lng, p_region, p_council_area, p_ward, p_photo_url,
    p_channel, p_citizen_name, p_citizen_phone, p_is_anonymous
  ) returning id into v_id;

  -- ROUTING ENGINE
  v_route := public.fn_route_complaint(v_id);
  select * into v_row from public.complaints where id = v_id;

  -- GROUPING
  v_gid := public.fn_group_complaint(v_id);

  -- AUDIT ROW (the timeline)
  insert into public.complaint_updates (
    complaint_id, actor_label, update_type, status_from, status_to,
    explanation, citizen_message, is_citizen_visible
  ) values (
    v_id, 'system', 'system', null, v_row.status::text::public.complaint_status,
    'Intake via ' || p_channel::text || '; routed: ' || coalesce(v_route->>'decision','?'),
    'Complaint received. Reference ' || v_row.tracking_no || '. ' ||
      coalesce((select name from public.institutions where id = v_row.institution_id), 'Central Desk') ||
      ' is responsible. We will update you here.',
    true
  );

  -- INTAKE NOTIFICATION (BLUEPRINT §10 template)
  perform public.fn_notify_citizen(
    v_id,
    'Received, reference ' || v_row.tracking_no || '. ' ||
      coalesce((select name from public.institutions where id = v_row.institution_id), 'Central Desk') ||
      ' is responsible. We will update you here.'
  );

  return v_row;
end $$;

-- ---------------------------------------------------------------------------
-- CONFIRM COMPLAINT — citizen confirms resolution (POST /reports/:tn/confirm).
-- Allowed: matching citizen_phone (tokenless, as sent in SMS/WhatsApp),
-- authenticated owner, officer of owning institution, or admin.
-- Only from citizen_confirmation / resolved.
-- ---------------------------------------------------------------------------
create or replace function public.confirm_complaint(
  p_tracking_no text,
  p_phone text default null
) returns boolean
language plpgsql volatile
as $$
declare
  c public.complaints%rowtype;
  v_allowed boolean := false;
begin
  select * into c from public.complaints
  where tracking_no = upper(btrim(p_tracking_no));
  if not found then
    return false;
  end if;

  if c.status not in ('citizen_confirmation','resolved') then
    return false;
  end if;

  -- phone match (case/space tolerant)
  if p_phone is not null and not c.is_anonymous
     and c.citizen_phone is not null
     and regexp_replace(c.citizen_phone, '[^0-9+]', '', 'g')
       = regexp_replace(p_phone, '[^0-9+]', '', 'g') then
    v_allowed := true;
  end if;

  -- authenticated owner
  if not v_allowed and auth.uid() is not null and c.citizen_id = auth.uid() then
    v_allowed := true;
  end if;

  -- admin
  if not v_allowed and public.fn_is_admin() then
    v_allowed := true;
  end if;

  -- officer of the owning institution
  if not v_allowed and public.fn_is_officer_of(c.id) then
    v_allowed := true;
  end if;

  if not v_allowed then
    return false;
  end if;

  update public.complaints
     set status = 'closed', closed_at = now()
   where id = c.id;

  insert into public.complaint_updates (
    complaint_id, actor_label, update_type, status_from, status_to,
    citizen_message, is_citizen_visible
  ) values (
    c.id, 'citizen', 'confirmation', c.status, 'closed',
    'Resolution confirmed by citizen. Thank you.', true
  );

  return true;
end $$;

-- ---------------------------------------------------------------------------
-- REOPEN COMPLAINT — citizen rejects the fix (POST /reports/:tn/reopen).
-- Same authorization as confirm; from citizen_confirmation/resolved/closed.
-- Increments reopened_count, re-enters officer queue, reopens the group.
-- ---------------------------------------------------------------------------
create or replace function public.reopen_complaint(
  p_tracking_no text,
  p_reason text,
  p_phone text default null
) returns boolean
language plpgsql volatile
as $$
declare
  c public.complaints%rowtype;
  v_allowed boolean := false;
begin
  if p_reason is null or length(btrim(p_reason)) < 5 then
    raise exception 'reopen_reason_required_min_5_chars';
  end if;

  select * into c from public.complaints
  where tracking_no = upper(btrim(p_tracking_no));
  if not found then
    return false;
  end if;

  if c.status not in ('citizen_confirmation','resolved','closed') then
    return false;
  end if;

  if p_phone is not null and not c.is_anonymous
     and c.citizen_phone is not null
     and regexp_replace(c.citizen_phone, '[^0-9+]', '', 'g')
       = regexp_replace(p_phone, '[^0-9+]', '', 'g') then
    v_allowed := true;
  end if;
  if not v_allowed and auth.uid() is not null and c.citizen_id = auth.uid() then
    v_allowed := true;
  end if;
  if not v_allowed and public.fn_is_admin() then
    v_allowed := true;
  end if;
  if not v_allowed and public.fn_is_officer_of(c.id) then
    v_allowed := true;
  end if;

  if not v_allowed then
    return false;
  end if;

  update public.complaints
     set status = 'reopened',
         closed_at = null,
         resolved_at = null,
         reopened_count = reopened_count + 1,
         -- fresh SLA window for the rework
         expected_response_at = public.fn_calculate_deadline(c.category_id, c.urgency)
   where id = c.id;

  insert into public.complaint_updates (
    complaint_id, actor_label, update_type, status_from, status_to,
    citizen_message, is_citizen_visible
  ) values (
    c.id, 'citizen', 'reopened', c.status, 'reopened',
    'Reopened by citizen: ' || btrim(p_reason), true
  );

  return true;
end $$;

0004_officer.sql:
-- ============================================================================
-- GamCiv AI — 0004_officer.sql
-- Authorization helpers + officer/admin RPCs
-- ============================================================================

-- ---------------------------------------------------------------------------
-- AUTHZ HELPERS
-- ---------------------------------------------------------------------------
create or replace function public.fn_is_admin()
returns boolean
language sql stable
security definer
set search_path = ''
as $$
  select coalesce(
    (select true from public.profiles p
     where p.user_id = auth.uid() and p.role = 'admin'),
    false
  );
$$;

create or replace function public.fn_my_institution()
returns uuid
language sql stable
security definer
set search_path = ''
as $$
  select o.institution_id
  from public.officers o
  where o.user_id = auth.uid()
  limit 1;
$$;

-- is the current user an officer/admin of the institution that owns c?
create or replace function public.fn_is_officer_of(
  p_complaint_id uuid
) returns boolean
language plpgsql stable
security definer
set search_path = ''
as $$
declare
  v_inst uuid;
  v_role text;
begin
  if auth.uid() is null then
    return false;
  end if;

  -- admins pass everything
  if public.fn_is_admin() then
    return true;
  end if;

  select institution_id into v_inst
  from public.complaints where id = p_complaint_id;
  if v_inst is null then
    return false;
  end if;

  -- via officers table (institution match)
  if exists (
    select 1 from public.officers o
    where o.user_id = auth.uid() and o.institution_id = v_inst
  ) then
    return true;
  end if;

  -- via profiles (role officer + organization)
  select role::text into v_role
  from public.profiles
  where user_id = auth.uid();
  if v_role = 'officer' then
    return exists (
      select 1 from public.officers o
      where o.user_id = auth.uid() and o.institution_id = v_inst
    );
  end if;

  return false;
end $$;

-- ---------------------------------------------------------------------------
-- OFFICER RPC: accept a case (submitted/received -> assigned)
-- ---------------------------------------------------------------------------
create or replace function public.fn_officer_accept(
  p_complaint_id uuid
) returns boolean
language plpgsql volatile security definer
set search_path = ''
as $$
declare
  c public.complaints%rowtype;
  v_officer public.officers%rowtype;
begin
  if not public.fn_is_officer_of(p_complaint_id) then
    return false;
  end if;

  select * into c from public.complaints where id = p_complaint_id;
  if c.status not in ('submitted','received','escalated') then
    return false;
  end if;

  select * into v_officer from public.officers where user_id = auth.uid() limit 1;

  update public.complaints
     set status = 'assigned',
         officer_id = v_officer.id,
         department_id = coalesce(c.department_id, v_officer.department_id)
   where id = c.id;

  insert into public.complaint_updates (
    complaint_id, actor_id, actor_label, update_type,
    status_from, status_to, explanation
  ) values (
    c.id, auth.uid(), 'officer', 'assignment',
    c.status, 'assigned', 'Case accepted by officer'
  );

  perform public.fn_notify_citizen(
    c.id,
    'Update: your report ' || c.tracking_no ||
    ' has been assigned to an officer.'
  );

  return true;
end $$;

-- ---------------------------------------------------------------------------
-- OFFICER RPC: reject a case (reason REQUIRED)
-- ---------------------------------------------------------------------------
create or replace function public.fn_officer_reject(
  p_complaint_id uuid,
  p_reason text
) returns boolean
language plpgsql volatile security definer
set search_path = ''
as $$
declare
  c public.complaints%rowtype;
begin
  if p_reason is null or length(btrim(p_reason)) < 10 then
    return false;
  end if;

  if not public.fn_is_officer_of(p_complaint_id) then
    return false;
  end if;

  select * into c from public.complaints where id = p_complaint_id;
  if c.status not in ('submitted','received','assigned','escalated') then
    return false;
  end if;

  update public.complaints set status = 'rejected' where id = c.id;

  insert into public.complaint_updates (
    complaint_id, actor_id, actor_label, update_type,
    status_from, status_to, explanation, citizen_message, is_citizen_visible
  ) values (
    c.id, auth.uid(), 'officer', 'status',
    c.status, 'rejected', p_reason,
    'Your report ' || c.tracking_no || ' was not accepted: ' || btrim(p_reason),
    true
  );

  perform public.fn_notify_citizen(
    c.id,
    'Your report ' || c.tracking_no || ' was not accepted: ' || btrim(p_reason)
  );

  return true;
end $$;

-- ---------------------------------------------------------------------------
-- OFFICER RPC: request info from citizen (status -> waiting_info)
-- ---------------------------------------------------------------------------
create or replace function public.fn_officer_request_info(
  p_complaint_id uuid,
  p_message text
) returns boolean
language plpgsql volatile security definer
set search_path = ''
as $$
declare
  c public.complaints%rowtype;
begin
  if p_message is null or length(btrim(p_message)) < 5 then
    return false;
  end if;

  if not public.fn_is_officer_of(p_complaint_id) then
    return false;
  end if;

  select * into c from public.complaints where id = p_complaint_id;
  if c.status not in ('assigned','in_progress','waiting_info') then
    return false;
  end if;

  update public.complaints set status = 'waiting_info' where id = c.id;

  insert into public.complaint_updates (
    complaint_id, actor_id, actor_label, update_type,
    status_from, status_to, citizen_message, is_citizen_visible
  ) values (
    c.id, auth.uid(), 'officer', 'status',
    c.status, 'waiting_info', btrim(p_message), true
  );

  perform public.fn_notify_citizen(c.id, btrim(p_message));

  return true;
end $$;

-- ---------------------------------------------------------------------------
-- OFFICER RPC: progress status (assigned -> in_progress -> citizen_confirmation)
-- ---------------------------------------------------------------------------
create or replace function public.fn_officer_set_status(
  p_complaint_id uuid,
  p_status text,
  p_citizen_message text default null
) returns boolean
language plpgsql volatile security definer
set search_path = ''
as $$
declare
  c public.complaints%rowtype;
  v_allowed boolean := false;
begin
  if not public.fn_is_officer_of(p_complaint_id) then
    return false;
  end if;

  select * into c from public.complaints where id = p_complaint_id;

  -- legal transitions
  if p_status = 'in_progress' and c.status in ('assigned','waiting_info') then
    v_allowed := true;
  elsif p_status = 'citizen_confirmation' and c.status in ('assigned','in_progress','waiting_info') then
    if p_citizen_message is null or length(btrim(p_citizen_message)) < 5 then
      return false;  -- resolution requires an explanation to the citizen
    end if;
    v_allowed := true;
  end if;

  if not v_allowed then
    return false;
  end if;

  update public.complaints
     set status = p_status::public.complaint_status,
         resolved_at = case when p_status = 'citizen_confirmation' then now() else resolved_at end,
         resolution_note = case when p_status = 'citizen_confirmation' then btrim(p_citizen_message) else resolution_note end
   where id = c.id;

  insert into public.complaint_updates (
    complaint_id, actor_id, actor_label, update_type,
    status_from, status_to, citizen_message, is_citizen_visible
  ) values (
    c.id, auth.uid(), 'officer', 'status',
    c.status, p_status::public.complaint_status,
    case when p_status = 'citizen_confirmation'
         then 'Crew reports fixed. Reply YES to confirm or NO to reopen.'
         else btrim(coalesce(p_citizen_message, 'Status updated: ' || p_status))
    end,
    true
  );

  perform public.fn_notify_citizen(
    c.id,
    case when p_status = 'citizen_confirmation'
         then 'Your report ' || c.tracking_no || ': crew reports fixed. Reply YES to confirm or NO to reopen.'
         else 'Update on your report ' || c.tracking_no || ': ' || p_status
    end
  );

  return true;
end $$;

-- ---------------------------------------------------------------------------
-- OFFICER RPC: internal note (never citizen-visible)
-- ---------------------------------------------------------------------------
create or replace function public.fn_officer_note(
  p_complaint_id uuid,
  p_note text
) returns boolean
language plpgsql volatile security definer
set search_path = ''
as $$
begin
  if p_note is null or length(btrim(p_note)) < 3 then
    return false;
  end if;
  if not public.fn_is_officer_of(p_complaint_id) then
    return false;
  end if;

  insert into public.complaint_updates (
    complaint_id, actor_id, actor_label, update_type, explanation, is_citizen_visible
  ) values (
    p_complaint_id, auth.uid(), 'officer', 'note', btrim(p_note), false
  );

  return true;
end $$;

-- ---------------------------------------------------------------------------
-- OFFICER RPC: attach proof (photo url; visible to citizen)
-- ---------------------------------------------------------------------------
create or replace function public.fn_officer_attach_proof(
  p_complaint_id uuid,
  p_photo_url text
) returns boolean
language plpgsql volatile security definer
set search_path = ''
as $$
declare
  c public.complaints%rowtype;
begin
  if p_photo_url is null or length(btrim(p_photo_url)) < 5 then
    return false;
  end if;
  if not public.fn_is_officer_of(p_complaint_id) then
    return false;
  end if;

  select * into c from public.complaints where id = p_complaint_id;

  update public.complaints
     set resolution_photo_url = coalesce(resolution_photo_url, btrim(p_photo_url))
   where id = c.id;

  insert into public.complaint_updates (
    complaint_id, actor_id, actor_label, update_type,
    citizen_message, is_citizen_visible
  ) values (
    c.id, auth.uid(), 'officer', 'attachment',
    'Proof attached by ' || c.tracking_no || ' handling team.', true
  );

  return true;
end $$;

0005_escalation.sql:
-- ============================================================================
-- GamCiv AI — 0005_escalation.sql
-- Officer forward/urgency RPCs, escalation sweep, auto-close sweep
-- ============================================================================

-- ---------------------------------------------------------------------------
-- OFFICER RPC: forward to another institution (reason REQUIRED).
-- BLUEPRINT §8: status -> forwarded; target becomes new owner; audit row.
-- ---------------------------------------------------------------------------
create or replace function public.fn_officer_forward(
  p_complaint_id uuid,
  p_institution_id uuid,
  p_reason text
) returns boolean
language plpgsql volatile security definer
set search_path = ''
as $$
declare
  c public.complaints%rowtype;
  v_target public.institutions%rowtype;
begin
  if p_reason is null or length(btrim(p_reason)) < 10 then
    return false;
  end if;

  if not public.fn_is_officer_of(p_complaint_id) then
    return false;
  end if;

  select * into v_target from public.institutions where id = p_institution_id;
  if not found then
    return false;
  end if;

  select * into c from public.complaints where id = p_complaint_id;
  if c.status not in ('submitted','received','assigned','in_progress','waiting_info','escalated') then
    return false;
  end if;

  if c.institution_id = v_target.id then
    return false;  -- forwarding to self is a no-op
  end if;

  update public.complaints
     set institution_id = v_target.id,
         department_id  = null,      -- receiving institution assigns its own
         officer_id     = null,
         status         = 'forwarded',
         expected_response_at = public.fn_calculate_deadline(c.category_id, c.urgency)
   where id = c.id;

  insert into public.complaint_updates (
    complaint_id, actor_id, actor_label, update_type,
    status_from, status_to, explanation, citizen_message, is_citizen_visible
  ) values (
    c.id, auth.uid(), 'officer', 'forward',
    c.status, 'forwarded',
    'Forwarded to ' || v_target.name || ': ' || btrim(p_reason),
    'Your report ' || c.tracking_no || ' has been forwarded to ' || v_target.name ||
      ' for handling.', true
  );

  perform public.fn_notify_citizen(
    c.id,
    'Your report ' || c.tracking_no || ' has been forwarded to ' || v_target.name || '.'
  );

  return true;
end $$;

-- ---------------------------------------------------------------------------
-- OFFICER RPC: change urgency (recomputes SLA deadline)
-- ---------------------------------------------------------------------------
create or replace function public.fn_officer_set_urgency(
  p_complaint_id uuid,
  p_urgency text
) returns boolean
language plpgsql volatile security definer
set search_path = ''
as $$
declare
  c public.complaints%rowtype;
  v_new public.urgency_level;
begin
  v_new := p_urgency::public.urgency_level;  -- raises if invalid

  if not public.fn_is_officer_of(p_complaint_id) then
    return false;
  end if;

  select * into c from public.complaints where id = p_complaint_id;
  if c.status in ('closed','rejected') then
    return false;
  end if;

  update public.complaints
     set urgency = v_new,
         expected_response_at = public.fn_calculate_deadline(c.category_id, v_new)
   where id = c.id;

  insert into public.complaint_updates (
    complaint_id, actor_id, actor_label, update_type,
    status_from, status_to, explanation, is_citizen_visible
  ) values (
    c.id, auth.uid(), 'officer', 'urgency',
    c.status, c.status,
    'Urgency changed ' || c.urgency::text || ' -> ' || v_new::text ||
      '; deadline recomputed.', false
  );

  return true;
end $$;

-- ---------------------------------------------------------------------------
-- ESCALATION SWEEP (runs via pg_cron / n8n every 15 min)
-- open statuses + deadline passed -> escalated; notify officer + citizen
-- ---------------------------------------------------------------------------
create or replace function public.fn_run_escalation_sweep()
returns integer
language plpgsql volatile security definer
set search_path = ''
as $$
declare
  v_count int := 0;
  r record;
begin
  for r in
    select id, tracking_no, urgency, expected_response_at, group_id
    from public.complaints
    where status in ('received','assigned','in_progress','waiting_info')
      and expected_response_at is not null
      and expected_response_at < now()
  loop
    update public.complaints
       set status = 'escalated'
     where id = r.id;

    insert into public.complaint_updates (
      complaint_id, actor_label, update_type,
      status_from, status_to, explanation, is_citizen_visible
    ) values (
      r.id, 'system', 'escalation',
      null, 'escalated',
      'Deadline passed (' || r.expected_response_at::text || ') — auto-escalated.',
      true
    );

    -- notify citizens in the same group too (group updates)
    perform public.fn_notify_citizen(
      r.id,
      'Your report ' || r.tracking_no ||
      ' passed its expected response time. It has been escalated. Reference kept.'
    );
    if r.group_id is not null then
      perform public.fn_notify_group(
        r.group_id,
        'An update on an incident near you: a related report was escalated.'
      );
    end if;

    v_count := v_count + 1;
  end loop;

  return v_count;
end $$;

-- ---------------------------------------------------------------------------
-- AUTO-CLOSE SWEEP (runs daily): cases resolved but unconfirmed for 72h are
-- closed by the system (BLUEPRINT: "no response in 72h → closed, actor system")
-- ---------------------------------------------------------------------------
create or replace function public.fn_run_autoclose_sweep()
returns integer
language plpgsql volatile security definer
set search_path = ''
as $$
declare
  v_count int := 0;
  r record;
begin
  for r in
    select id, tracking_no
    from public.complaints
    where status in ('citizen_confirmation','resolved')
      and resolved_at is not null
      and resolved_at < now() - interval '72 hours'
  loop
    update public.complaints
       set status = 'closed', closed_at = now()
     where id = r.id;

    insert into public.complaint_updates (
      complaint_id, actor_label, update_type,
      status_from, status_to, explanation, citizen_message, is_citizen_visible
    ) values (
      r.id, 'system', 'status',
      null, 'closed',
      'Auto-closed after 72h without citizen response.',
      'No response received, so your report ' || r.tracking_no ||
        ' has been closed. Thank you.', true
    );

    perform public.fn_notify_citizen(
      r.id,
      'No response received for your report ' || r.tracking_no ||
      ', so it has been closed. Thank you.'
    );

    v_count := v_count + 1;
  end loop;

  return v_count;
end $$;

0007_rls.sql:
-- ============================================================================
-- GamCiv AI — 0007_rls.sql
-- Row Level Security policies for all public tables + grants
-- Model (BLUEPRINT §11):
--   - anon: read non-sensitive data only
--   - authenticated citizen: own complaints
--   - officers: read/update only their institution's complaints
--   - admin: everything
-- ============================================================================

-- ---------------------------------------------------------------------------
-- ENABLE RLS ON ALL TABLES
-- ---------------------------------------------------------------------------
alter table public.institutions      enable row level security;
alter table public.departments       enable row level security;
alter table public.profiles          enable row level security;
alter table public.officers          enable row level security;
alter table public.categories        enable row level security;
alter table public.complaint_groups  enable row level security;
alter table public.complaints        enable row level security;
alter table public.complaint_updates enable row level security;
alter table public.notifications     enable row level security;
alter table public.audit_log         enable row level security;

-- Public consumers (map, tracking) use the security-definer functions and
-- views; direct row access is not granted to anon (citizen fields stay sealed).
revoke select on public.complaints        from anon;
revoke select on public.complaint_updates from anon;
revoke select on public.notifications     from anon;
revoke select on public.audit_log         from anon;

-- ---------------------------------------------------------------------------
-- PUBLIC REFERENCE TABLES: institutions, departments, categories
-- Everyone can read; only admins write.
-- ---------------------------------------------------------------------------
create policy "inst_select_all" on public.institutions
  for select using (true);

create policy "inst_admin_write" on public.institutions
  for all to authenticated
  using (public.fn_is_admin()) with check (public.fn_is_admin());

create policy "dept_select_all" on public.departments
  for select using (true);

create policy "dept_admin_write" on public.departments
  for all to authenticated
  using (public.fn_is_admin()) with check (public.fn_is_admin());

create policy "cat_select_all" on public.categories
  for select using (true);

create policy "cat_admin_write" on public.categories
  for all to authenticated
  using (public.fn_is_admin()) with check (public.fn_is_admin());

-- ---------------------------------------------------------------------------
-- PROFILES: self + admin
-- ---------------------------------------------------------------------------
create policy "prof_select_self_or_admin" on public.profiles
  for select using (
    user_id = auth.uid() or public.fn_is_admin()
  );

create policy "prof_insert_self" on public.profiles
  for insert with check (user_id = auth.uid());

create policy "prof_update_self" on public.profiles
  for update using (user_id = auth.uid())
  with check (user_id = auth.uid());

-- ---------------------------------------------------------------------------
-- OFFICERS: readable by all authenticated (for assignment UIs),
-- writable by admin; officer may update own row
-- ---------------------------------------------------------------------------
create policy "officers_select_authenticated" on public.officers
  for select to authenticated using (true);

create policy "officers_admin_all" on public.officers
  for all to authenticated
  using (public.fn_is_admin()) with check (public.fn_is_admin());

create policy "officers_self_update" on public.officers
  for update to authenticated
  using (user_id = auth.uid()) with check (user_id = auth.uid());

-- ---------------------------------------------------------------------------
-- COMPLAINTS: the heart of the security model
-- SELECT: admin all / officer own-institution / citizen own / anon non-sensitive
-- INSERT: authenticated (own) + service_role
-- UPDATE/DELETE: admin + owning institution's officers + service_role
-- ---------------------------------------------------------------------------
create policy "comp_select_admin" on public.complaints
  for select to authenticated
  using (public.fn_is_admin());

create policy "comp_select_officer_own_inst" on public.complaints
  for select to authenticated
  using (
    exists (
      select 1 from public.officers o
      where o.user_id = auth.uid()
        and o.institution_id = complaints.institution_id
    )
  );

create policy "comp_select_citizen_own" on public.complaints
  for select to authenticated
  using (citizen_id = auth.uid());

create policy "comp_insert_citizen" on public.complaints
  for insert to authenticated with check (citizen_id = auth.uid());

create policy "comp_insert_service" on public.complaints
  for insert to service_role with check (true);

create policy "comp_update_officer" on public.complaints
  for update to authenticated
  using (
    public.fn_is_admin() or exists (
      select 1 from public.officers o
      where o.user_id = auth.uid()
        and o.institution_id = complaints.institution_id
    )
  )
  with check (
    public.fn_is_admin() or exists (
      select 1 from public.officers
      where user_id = auth.uid()
        and institution_id = complaints.institution_id
    )
  );

create policy "comp_delete_admin" on public.complaints
  for delete to authenticated using (public.fn_is_admin());

create policy "comp_delete_service" on public.complaints
  for delete to service_role using (true);

-- ---------------------------------------------------------------------------
-- COMPLAINT_UPDATES: same audience as the complaint, but internal rows
-- (is_citizen_visible = false) only for staff. Writes: staff + service only.
-- ---------------------------------------------------------------------------
create policy "upd_select_staff" on public.complaint_updates
  for select to authenticated
  using (
    public.fn_is_admin() or exists (
      select 1
      from public.complaints c
      join public.officers o
        on o.user_id = auth.uid() and o.institution_id = c.institution_id
      where c.id = complaint_updates.complaint_id
    )
  );

create policy "upd_select_citizen" on public.complaint_updates
  for select to authenticated
  using (
    exists (
      select 1 from public.complaints c
      where c.id = complaint_updates.complaint_id
        and c.citizen_id = auth.uid()
    ) and is_citizen_visible
  );

create policy "upd_insert_staff" on public.complaint_updates
  for insert to authenticated with check (
    public.fn_is_admin() or exists (
      select 1
      from public.complaints c
      join public.officers o
        on o.user_id = auth.uid() and o.institution_id = c.institution_id
      where c.id = complaint_updates.complaint_id
    )
  );

create policy "upd_insert_service" on public.complaint_updates
  for insert to service_role with check (true);

-- ---------------------------------------------------------------------------
-- NOTIFICATIONS: n8n/service writes; staff reads
-- ---------------------------------------------------------------------------
create policy "notif_select_staff" on public.notifications
  for select to authenticated
  using (
    public.fn_is_admin() or exists (
      select 1
      from public.complaints c
      join public.officers o
        on o.user_id = auth.uid() and o.institution_id = c.institution_id
      where c.id = notifications.complaint_id
    )
  );

create policy "notif_insert_service" on public.notifications
  for insert to service_role with check (true);

create policy "notif_update_service" on public.notifications
  for update to service_role using (true) with check (true);

-- ---------------------------------------------------------------------------
-- AUDIT_LOG: admin only (service for system rows)
-- ---------------------------------------------------------------------------
create policy "audit_admin_all" on public.audit_log
  for all to authenticated
  using (public.fn_is_admin()) with check (public.fn_is_admin());

create policy "audit_service_all" on public.audit_log
  for all to service_role using (true) with check (true);

-- ---------------------------------------------------------------------------
-- COMPLAINT_GROUPS: readable by all, admin/service write
-- ---------------------------------------------------------------------------
create policy "grp_select_all" on public.complaint_groups
  for select using (true);

create policy "grp_admin_write" on public.complaint_groups
  for all to authenticated
  using (public.fn_is_admin()) with check (public.fn_is_admin());

create policy "grp_service_write" on public.complaint_groups
  for all to service_role using (true) with check (true);

-- ---------------------------------------------------------------------------
-- GRANTS — RPCs
-- ---------------------------------------------------------------------------
-- Public intake + citizen flows (anon allowed: no signup wall)
grant execute on function
  public.submit_complaint(text, text, uuid, numeric, public.urgency_level,
                          numeric, numeric, text, text, text, text,
                          public.report_channel, text, text, boolean)
to anon, authenticated;

grant execute on function
  public.confirm_complaint(text, text) to anon, authenticated;
grant execute on function
  public.reopen_complaint(text, text, text) to anon, authenticated;

-- Officer/admin RPCs
grant execute on function
  public.fn_officer_accept(uuid),
  public.fn_officer_reject(uuid, text),
  public.fn_officer_request_info(uuid, text),
  public.fn_officer_set_status(uuid, text, text),
  public.fn_officer_note(uuid, text),
  public.fn_officer_forward(uuid, uuid, text),
  public.fn_officer_set_urgency(uuid, text)
to authenticated;

grant execute on function
  public.fn_admin_route(uuid, uuid, uuid, text),
  public.fn_central_desk_queue()
to authenticated;

-- System sweeps (service role / cron)
grant execute on function
  public.fn_run_escalation_sweep(),
  public.fn_run_autoclose_sweep()
to service_role;
